  4	method MirrorImage<T>(m: array2<T>)
  5	  modifies m
  6	  ensures forall i,j :: 0 <= i < m.Length0 && 0 <= j < m.Length1 ==>
  7	            m[i,j] == old(m[i, m.Length1-1-j])
  8	{
  9	  var a := 0;
 10	  while a < m.Length0
 11	    invariant a <= m.Length0
 12	    invariant forall i,j :: 0 <= i && i < a && 0 <= j && j < m.Length1 ==>
 13	                m[i,j] == old(m[i, m.Length1-1-j])
 14	    invariant forall i,j :: a <= i && i < m.Length0 && 0 <= j && j < m.Length1 ==>
 15	                m[i,j] == old(m[i,j])
 16	  {
 17	    var b := 0;
 18	    while b < m.Length1 / 2
 19	      invariant  b <= m.Length1 / 2
 20	      invariant forall i,j :: 0 <= i && i < a && 0 <= j && j < m.Length1 ==>
 21	                  m[i,j] == old(m[i, m.Length1-1-j])
 22	      invariant forall j :: 0 <= j && j < b ==>
 23	                  m[a,j] == old(m[a, m.Length1-1-j]) &&
 24	                  old(m[a,j]) == m[a, m.Length1-1-j]
 25	      invariant forall j :: b <= j && j < m.Length1-b ==> m[a,j] == old(m[a,j])
 26	      invariant forall i,j :: a+1 <= i && i < m.Length0 && 0 <= j && j < m.Length1 ==>
 27	                  m[i,j] == old(m[i,j])
 28	    {
 29	      m[a, m.Length1-1-b], m[a, b] := m[a, b], m[a, m.Length1-1-b];
 30	      b := b + 1;
 31	    }
 32	    a := a + 1;
 33	  }
 34	}
 35	
 36	method Flip<T>(m: array2<T>)
 37	  requires m.Length0 == m.Length1
 38	  modifies m
 39	  ensures forall i,j :: 0 <= i < m.Length0 && 0 <= j < m.Length1 ==> m[i,j] == old(m[j,i])
 40	{
 41	  var N := m.Length0;
 42	  var a := 0;
 43	  var b := 1;
 44	  while a != N
 45	    invariant a < b <= N || (a == N && b == N+1)
 46	    invariant forall i,j :: 0 <= i <= j < (N) - 1 ==>
 47	                if i < a || (i == a && j < b)
 48	                  then m[i,j] == old(m[j,i]) && m[j,i] == old(m[i,j])
 49	                  else m[i,j] == old(m[i,j]) && m[j,i] == old(m[j,i])
 50	    decreases N-a, N-b
 51	  {
 52	    if b < N {
 53	      m[a,b], m[b,a] := m[b,a], m[a,b];
 54	      b := b + 1;
 55	    } else {
 56	      a := a + 1;  b := a + 1;
 57	    }
 58	  }
 59	}
 60	
 61	method Main()
 62	{
 63	  var B := new bool[2,5];
 64	  B[0,0] := true;  B[0,1] := false;  B[0,2] := false;  B[0,3] := true;  B[0,4] := false;
 65	  B[1,0] := true;  B[1,1] := true;   B[1,2] := true;   B[1,3] := true;  B[1,4] := false;
 66	  print "Before:\n";
 67	  PrintMatrix(B);
 68	  MirrorImage(B);
 69	  print "Mirror image:\n";
 70	  PrintMatrix(B);
 71	
 72	  var A := new int[3,3];
 73	  A[0,0] := 5;  A[0,1] := 7;  A[0,2] := 9;
 74	  A[1,0] := 6;  A[1,1] := 2;  A[1,2] := 3;
 75	  A[2,0] := 7;  A[2,1] := 1;  A[2,2] := 0;
 76	  print "Before:\n";
 77	  PrintMatrix(A);
 78	  Flip(A);
 79	  print "Flip:\n";
 80	  PrintMatrix(A);
 81	}
 82	
 83	method PrintMatrix<T>(m: array2<T>)
 84	{
 85	  var i := 0;
 86	  while i < m.Length0 {
 87	    var j := 0;
 88	    while j < m.Length1 {
 89	      print m[i,j];
 90	      j := j + 1;
 91	      if j == m.Length1 {
 92	        print "\n";
 93	      } else {
 94	        print ", ";
 95	      }
 96	    }
 97	    i := i + 1;
 98	  }
 99	}
